        token.setTargetLiquidity(1_000_000, 1);
        token.setTargetLiquidity(0, 1_000_000);
        vm.stopPrank();

        console2.log("--- AFTER-TRIGGER: testSetTargetLiquidityWithoutValidation ---");
        (uint256 liqAfter, uint256 liqDenomAfter) = (token.targetLiquidity(), token.targetLiquidityDenominator());
        console2.log("After: liquidity=%d, denominator=%d", liqAfter, liqDenomAfter);

        if (liqAfter == 0 && liqDenomAfter == 1_000_000) {
            console2.log("Vulnerability Exists: liquidity targets set w/validation");
        } else {
            console2.log("Vulnerability not Exist: Liquidity validation exists");
