            100,  // liquidityFee (10%)
            100,  // treasuryFee (10%)
            feeDenom,
            100,  // firePitFee (10%)
            0,0,0,
            100   // riskFreeValueFee (10%)
        );
        vm.stopPrank();

        console2.log("--- AFTER-TRIGGER: testSetMaxFeesWithoutValidation ---");
        (uint256 liqFeeAfter, uint256 treFeeAfter, uint256 fireFeeAfter, uint256 riskFeeAfter) = (
            token.liquidityFee(),
            token.treasuryFee(),
            token.firePitFee(),
            token.riskFreeValueFee()
        );
        uint256 totalFeeAfter = token.totalFee();
        console2.log(
            "After: fees liquidity=%d, treasury=%d, fire=%d, risk=%d, total=%d", 
            liqFeeAfter, 
            treFeeAfter, 
            fireFeeAfter, 
            riskFeeAfter, 
            totalFeeAfter
        );

        if (totalFeeAfter == 400) {
            console2.log("Vulnerability Exists: dangerous fee settings accepted");
        } else {
            console2.log("Vulnerability not Exist: Fee validation exists");
        }
    }
}
